+/** Parses `git diff --numstat -z`; binary files report null counts. */
+export function parseNumstat(
+	output: string,
+): Map<string, { additions: number | null; deletions: number | null }> {
+	const counts = new Map<
+		string,
+		{ additions: number | null; deletions: number | null }
+	>();
+	const records = output.split("\0");
+	for (let index = 0; index < records.length; index++) {
+		const record = records[index];
+		if (!record) continue;
+		const [add, del, inlinePath] = record.split("\t");
+		let path = inlinePath;
+		if (path === undefined) continue;
+		// Renames: `add\tdel\t\0old\0new\0`.
+		if (path === "") {
+			index += 2;
+			path = records[index] ?? "";
+		}
+		if (!path) continue;
+		counts.set(path, {
+			additions: add === "-" ? null : Number(add),
+			deletions: del === "-" ? null : Number(del),
+		});
+	}
+	return counts;
