+		counts: Map<string, { additions: number | null; deletions: number | null }>,
+	): SourceControlFile[] =>
+		files.map((file) => ({
+			...file,
+			additions: counts.get(file.path)?.additions ?? null,
+			deletions: counts.get(file.path)?.deletions ?? null,
+		}));
